WITH customer_metrics AS ( SELECT c.c_customer_sk, c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_income_band_sk, SUM(ss.ss_net_paid) AS total_net_paid, AVG(ss.ss_ext_discount_amt) AS avg_discount_amount, COUNT(DISTINCT ss.ss_store_sk) AS distinct_store_visits, CASE WHEN SUM(ss.ss_net_paid) > 5000 THEN 'Platinum' WHEN SUM(ss.ss_net_paid) > 2000 THEN 'Gold' WHEN SUM(ss.ss_net_paid) > 500 THEN 'Silver' ELSE 'Bronze' END AS loyalty_tier FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk GROUP BY c.c_customer_sk, c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_income_band_sk ) SELECT c_customer_id, c_first_name, c_last_name, hd_income_band_sk, total_net_paid, avg_discount_amount, distinct_store_visits, loyalty_tier, DENSE_RANK() OVER (PARTITION BY loyalty_tier ORDER BY total_net_paid DESC) AS tier_rank FROM customer_metrics ORDER BY loyalty_tier, tier_rank
